168	    /**
169	     * Run the simulation from its current state for a single step.
170	     * Iterate over the whole field updating the state of each actor.
171	     */
172	    public void simulateOneStep()
173	    {
174	        step++;
175	        time.incrementTime(); 
176	        weatherCond = weatherCond.nextCondition();
177	        // Provide space for newborn actors.
178	
179	        List<Actor> newActors = new ArrayList<>();        
180	        // Let all actors act.
181	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
182	            Actor actor = it.next();
183	            actor.act(newActors, weatherCond);
184	            if(! actor.isAlive()) {
185	                it.remove();
186	            }
187	        }
188	
189	        // Add the newly born actors to the main lists.
190	        actors.addAll(newActors);
191	
192	        view.showStatus(step, field, weatherCond, diseases);
193	        field.setWeatherField(weatherCond);
194	    }
