209	    /**
210	     * Randomly populate the field with actors.
211	     * Actors can only populate areas they will survive in
212	     * i.e. actors that will not survive in water cannot be placed there.
213	     */
214	    private void populate()
215	    {
216	        Random rand = Randomizer.getRandom();
217	        field.clear();
218	        for(int row = 0; row < field.getDepth(); row++) {
219	            for(int col = 0; col < field.getWidth(); col++) {
220	                for (SpawnRule rule : spawnRules){
221	                    Location location = new Location(row, col);
222	                    if(rand.nextDouble() <= rule.probability && field.canTraverse(rule.prototype, location)) {
223	                        Actor newActor = rule.prototype.birth(new Location(row, col), Collections.emptySet());
224	                        actors.add(newActor);
225	                        break;
226	                    }
227	                }
228	            }
229	        }
230	    }
